import {createNavigation,screen} from './navigation.mjs';
import {loadConfig} from './connection.mjs';
import {totals,loanTerms,interest} from './paper-math.mjs';
import {identity,marketOf,statusLabel,chartData} from './presentation.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>(n/100).toLocaleString('en-US',{style:'currency',currency:'USD'}),signed=n=>(n<0?'−':'+')+money(Math.abs(n)),time=t=>t?new Date(t).toLocaleString('en-US',{timeZone:'America/New_York',timeZoneName:'short'}):'Not started',cents=n=>Number.isFinite(n)?(n/100).toFixed(2)+'¢':'Unavailable';
let initializing=null,session=null,config=null,data=null,pending=null,busy=false,view=screen(location.hash.slice(1)),recordings=[],selected='',record=null,history=[],replay=null,playing=null;
const navigation=createNavigation(view);let navigatingBack=false;const avatars=new Map();
try{session=JSON.parse(sessionStorage.getItem('market-lab:auth:v1')||'null');}catch{}
function authSave(){if(session)sessionStorage.setItem('market-lab:auth:v1',JSON.stringify(session));else sessionStorage.removeItem('market-lab:auth:v1');}
async function token(){if(!session)throw Error('Sign in first.');if(session.expires_at*1000<Date.now()+60000){const r=await fetch(config.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok){session=null;authSave();throw Error('Session expired. Sign in again.');}session=await r.json();authSave();}return session.access_token;}
async function api(path,body){const r=await fetch('/api/lab/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+await token(),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'Workspace access failed');return d;}
function metric(label,value,cls=''){return `<div class="metric"><label>${label}</label><div class="value ${cls}">${value}</div></div>`;}
function agentHead(a){const i=identity(a.id);return `<div class="agent"><span class="avatar ${a.id==='B'?'beta':''}" data-avatar="${esc(a.avatarId||'')}">${i.appId==='Beta'?'B':'A'}</span><div><h2>${i.name}</h2><span class="small">Permanent ID: <strong>${i.appId}</strong></span></div></div>`;}
function home(){const count=data.state.agents.reduce((n,a)=>n+a.applications.filter(x=>x.status==='pending').length+(a.imageRequests||[]).filter(x=>x.status==='pending').length,0);return `<div class="home-grid">${[['recordings','▣','Recorded tickers','Watch & replay investments'],['trading','↗','Agent trading','Choices, buys & sells'],['profiles','♙','Agent profiles','Cash, results & pictures'],['loans','▤','Requests & approvals',count?count+' awaiting your review':'Loans & profile pictures']].map(([v,icon,title,sub])=>`<a class="home-tile" href="#${v}"><span class="tile-icon">${icon}</span><strong>${title}</strong><small>${sub}</small></a>`).join('')}</div>${data.state.agents.map(a=>`<section class="panel">${agentHead(a)}<div class="row"><span>Available cash</span><strong>${money(a.cash)}</strong></div><small>${a.positions.length} open investment(s) · ${esc(a.status||'Waiting')}</small></section>`).join('')}<a href="#settings">Settings & experiment controls →</a>`;}
function decision(a){const d=a.decision;if(!d)return '<p class="muted">No decision recorded yet.</p>';return `<div class="decision"><h3>Latest choice: ${esc(d.action)}</h3><p>${esc(d.summary)}</p><small>${time(d.at)}</small>${marketLink(d.market)}<details data-key="decision-${a.id}"><summary>Evidence & exit plan</summary><p><strong>Evidence:</strong> ${esc(d.evidence)}</p><p><strong>Exit plan:</strong> ${esc(d.exitPlan)}</p><p><strong>Research hypothesis:</strong> ${esc(d.lesson)}</p><small>Recorded explanation; probability estimates are unverified.</small></details></div>`;}
function marketLink(t){return t?`<button class="record-link" data-record="${esc(t)}">View exact market & recording →</button><small>${esc(t)}</small>`:'';}
function event(e){const i=e.agent?identity(e.agent):null,t=marketOf(e);return `<article class="trade"><time>${time(e.at)}</time><strong style="color:${i?.color||'#fff'}">${i?i.name+' · '+i.appId+' — ':''}${esc(statusLabel(e))}</strong><p>${esc(e.reason||e.detail||e.order?.reason||e.decision?.summary||e.application?.reason||'Recorded account event')}</p>${e.quantity?`<p>${e.quantity} ${esc(e.side||'')} contracts ${Number.isFinite(e.price)?'at '+cents(e.price):''}${e.fee!==undefined?' · Fees '+money(e.fee):''}</p>`:''}${Number.isFinite(e.pnl)?`<p class="${e.pnl<0?'negative':'positive'}">Result after fees: ${signed(e.pnl)}</p>`:''}${t?marketLink(t):''}<details data-key="event-${esc(e.recordId||e.order?.id||e.order||e.at+'-'+e.agent+'-'+e.type)}"><summary>Full recorded details</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details></article>`;}
function trading(){return `<div class="grid">${data.state.agents.map(a=>`<section class="panel">${agentHead(a)}<p class="badge">${esc(a.status||'Waiting')}</p>${decision(a)}<h3>Open investments</h3>${a.positions.map(p=>`<div class="note"><strong>${p.quantity} ${esc(p.side)} · Cost ${money(p.cost)}</strong><p>Estimated value ${money(p.mark??p.cost)} ${p.markStale?'· STALE':''}</p>${marketLink(p.market)}</div>`).join('')||'<p class="muted">No open investment.</p>'}${a.orders.map(o=>`<p>Pending ${esc(o.action)} ${esc(o.side)} · Limit ${cents(o.limit)}</p>${marketLink(o.market)}`).join('')}</section>`).join('')}<section class="panel full"><h2>Activity & explanations</h2><p class="small">Updates never close what you are reading. Tap New activity when ready.</p>${(history.length?history.toReversed():data.events).map(event).join('')||'<p>No activity yet.</p>'}</section></div>`;}
function profiles(){return `<div class="grid">${data.state.agents.map(a=>{const t=totals(a);return `<section class="panel">${agentHead(a)}<div class="metrics">${metric('Available',money(t.cash))}${metric('Invested',money(t.invested))}${metric('Made / lost',signed(t.realized),t.realized<0?'negative':'positive')}</div><dl>${[['Starting balance',money(a.start)],['Open gain / loss',signed(t.unrealized)],['Debt',money(t.debt)],['Interest owed',money(t.interest)],['Net account value',money(t.net)],['Pictures purchased',money(a.cosmeticSpent||0)],['Owner adjustments',money(a.ownerCredits||0)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><p>${a.id==='A'?'Focus: BTC 15-minute rounds.':'Chooses short- or longer-term opportunities across the discovered Kalshi markets, up to 30 days.'}</p><a href="#trading">View trading activity →</a><details data-key="picture-${a.id}"><summary>Profile picture & requests</summary><p>One free picture. Extra pictures cost $5 of eligible earned profit and require your approval.</p>${(a.imageRequests||[]).map(r=>`<p>${r.free?'First free picture':'New picture request'}: <strong>${esc(r.status)}</strong>${r.error?' · '+esc(r.error):''}</p>`).join('')||'<p>First picture awaiting setup.</p>'}${(a.images||[]).map(im=>`<span class="avatar" data-avatar="${esc(im.id)}">${identity(a.id).appId}</span><small>${time(im.createdAt)} · ${esc(im.prompt)}</small>`).join('')}</details><details data-key="performance-${a.id}"><summary>Research & performance history</summary><p>Largest drawdown: ${money(a.maxDrawdown)} · Fees paid: ${money(a.fees)}</p>${decision(a)}</details></section>`;}).join('')}<section class="panel full"><h2>Experiment reviews</h2>${data.state.checkpoints.map(c=>`<h3>Day ${c.day} · ${time(c.at)}</h3>${c.accounts.map(a=>`<p>${identity(a.id).appId}: ${money(a.net)} net value</p>`).join('')}`).join('')||'<p>Reviews appear on days 10, 20, and 30.</p>'}</section></div>`;}
function loanCards(){const s=data.state,apps=s.agents.flatMap(a=>a.applications.map(x=>({...x,agent:a.id}))).toReversed(),principal=s.agents.reduce((n,a)=>n+totals(a).debt,0);return `<div class="banktop">${metric('Available to lend',money(s.bank.available))}${metric('Outstanding principal',money(principal))}${metric('Pending requests',apps.filter(x=>x.status==='pending').length)}</div>${apps.map(x=>`<article class="panel loan"><div class="row"><h2>${identity(x.agent).appId} requests ${money(x.amount)}</h2><span class="badge">${esc(x.status)}</span></div><p>${esc(x.reason)}</p><dl><div><dt>Annual simple interest</dt><dd>${x.apr}%</dd></div><div><dt>Interest for 30 days on requested amount</dt><dd>${money(Math.ceil(x.amount*x.apr/100*30/365))}</dd></div><div><dt>Term</dt><dd>Due 30 days after funding; early repayment allowed</dd></div></dl>${x.status==='pending'?`<label>Approve amount ($)<input type="number" min="1" max="${x.amount/100}" step="0.01" value="${x.amount/100}" data-amount="${esc(x.id)}"></label><div class="actions"><button class="primary" data-loan="${esc(x.id)}" data-approve="true">Approve fake loan</button><button data-loan="${esc(x.id)}" data-approve="false">Deny</button></div>`:`<p class="small">Reviewed ${time(x.reviewedAt)}${x.approvedAmount?' · Funded '+money(x.approvedAmount):''}</p>`}</article>`).join('')||'<section class="panel"><h2>No applications yet</h2><p>An agent must submit a request with its plan before you can approve it.</p></section>'}<section class="panel"><h2>Bank policy · 23% starting annual interest</h2><p>First loan: up to $50 / $250. After successful repayment: up to $100 / $500. Additional borrowing with unpaid debt: up to $25 / $125 at 28%, then $10 / $50 at 33%. No further supplemental loans until debt is cleared.</p><p>Outstanding principal never exceeds $100 for AlphaBot or $500 for Beta. Every loan requires your approval; existing loans keep their agreed rates.</p>${s.agents.map(a=>`<h3>${esc(a.name||'Agent '+a.id)}</h3><p class="small">Current maximum new request: ${money(loanTerms(a).limit)} at ${loanTerms(a).apr}% annually</p>${a.loans.map(l=>`<p>Principal ${money(l.principal)} · interest ${money(interest(l))} · ${l.apr}% annual · due ${time(l.dueAt)}${l.dueAt<Date.now()?' · OVERDUE':''}</p>`).join('')}`).join('')}</section>`;}
function loans(){return `<section class="panel"><h2>Picture requests</h2>${data.state.agents.flatMap(a=>(a.imageRequests||[]).filter(r=>!r.free).map(r=>`<article class="trade"><h3>${identity(a.id).name} · ${identity(a.id).appId}</h3><p>New profile picture · ${money(r.price)} fake profit · ${esc(r.status)}</p><p>${esc(r.reason)}</p><p>${esc(r.prompt)}</p>${r.status==='pending'?`<div class="actions"><button class="primary" data-image="${esc(r.id)}" data-agent="${a.id}" data-approve="true">Approve picture</button><button data-image="${esc(r.id)}" data-agent="${a.id}" data-approve="false">Decline</button></div>`:''}</article>`)).join('')||'<p>No paid picture requests. The first picture for each agent is free.</p>'}</section>${loanCards()}`;}
function recordingList(){return `<p class="small">Recorded quotes arrive about once a minute while running. Historical candles are labeled separately. No invented prices or stitched rounds.</p>${recordings.map(m=>`<section class="panel recording-card"><div class="row"><span class="badge">${esc(m.status)}</span><small>Closes ${time(m.close_time)}</small></div><h2>${esc(m.title||m.ticker)}</h2><p>${esc(m.yes_sub_title||m.subtitle||'')}</p><small>${esc(m.ticker)}</small><button class="primary" data-record="${esc(m.ticker)}">Open recording</button></section>`).join('')||'<section class="panel"><h2>No recordings yet</h2><p>Recordings appear as markets are observed. Existing positions will be linked when their records are prepared.</p></section>'}`;}
function chart(record,cutoff=null){const {points,markers,connections}=chartData(record.frames,record.events),visible=cutoff===null?points:points.filter(p=>p.at<=Date.parse(record.frames[cutoff]?.at)),end=cutoff===null?Infinity:visible.at(-1)?.at;if(!visible.length)return '<p class="empty">No usable prices recorded. Missing history is never filled with invented movement.</p>';const allTimes=[...points.map(p=>p.at),...markers.map(m=>m.t)],start=Math.min(...allTimes),finish=Math.max(...allTimes,start+60000),x=t=>55+(t-start)/(finish-start)*680,y=p=>260-p/10000*220;
 const candles=visible.filter(p=>[p.open,p.high,p.low,p.close].every(Number.isFinite));let drawing='';
 if(candles.length)drawing=candles.map(p=>{const color=p.close>=p.open?'#32d998':'#ff5d70';return `<line x1="${x(p.at)}" x2="${x(p.at)}" y1="${y(p.low)}" y2="${y(p.high)}" stroke="${color}"/><rect x="${x(p.at)-2}" y="${Math.min(y(p.open),y(p.close))}" width="4" height="${Math.max(2,Math.abs(y(p.open)-y(p.close)))}" fill="${color}"/>`;}).join('');
 // Gaps larger than two minutes remain disconnected; quote samples never become fabricated candles.
 const quotePoints=visible.filter(p=>p.source==='recorded-quote');for(let n=0;n<quotePoints.length;n++){const p=quotePoints[n],prev=quotePoints[n-1];if(prev&&p.at-prev.at<=120000)drawing+=`<line x1="${x(prev.at)}" y1="${y(prev.close)}" x2="${x(p.at)}" y2="${y(p.close)}" stroke="#5498ff" stroke-width="1.5"/>`;else drawing+=`<circle cx="${x(p.at)}" cy="${y(p.close)}" r="2" fill="#5498ff"/>`;}
 for(const c of connections.filter(c=>c.exit.t<=end))drawing+=`<line x1="${x(c.entry.t)}" y1="${y(c.entry.yesPrice)}" x2="${x(c.exit.t)}" y2="${y(c.exit.yesPrice)}" stroke="${c.pnl>=0?'#32d998':'#ff5d70'}" stroke-width="2" stroke-dasharray="5 4"/>`;
 const trades=markers.filter(m=>end===undefined||m.t<=end);for(const m of trades){const color=m.type!=='BUY'&&Number.isFinite(m.pnl)?(m.pnl>=0?'#32d998':'#ff5d70'):identity(m.agent).color;drawing+=`<circle cx="${x(m.t)}" cy="${y(m.yesPrice)}" r="5" fill="${color}"/><text class="mark" x="${Math.max(58,Math.min(620,x(m.t)-30))}" y="${Math.max(22,y(m.yesPrice)-14)}" style="fill:${color}">${esc(identity(m.agent).appId)} ${m.type} ${m.type==='SETTLE'?signed(m.pnl):cents(m.price)}</text>`;}
 return `<svg class="chart" viewBox="0 0 780 310" role="img" aria-label="YES contract prices with recorded buy and sell markers">${[0,2500,5000,7500,10000].map(p=>`<line x1="55" x2="735" y1="${y(p)}" y2="${y(p)}" stroke="#2b3039"/><text x="8" y="${y(p)+4}">${p/100}¢</text>`).join('')}${drawing}<text x="55" y="292">${new Date(start).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</text><text x="665" y="292">${new Date(finish).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</text></svg>`;
}
function recordingDetail(){if(!record)return '<p>Loading recording…</p>';const m=record.metadata||{ticker:selected},frames=record.frames||[];return `<button data-record-list>← All recordings</button><section class="panel"><h2>${esc(m.title||m.ticker)}</h2><p>${esc(m.yes_sub_title||m.subtitle||'')}</p><small>${esc(m.ticker)}</small><p class="chart-label">YES contract price in cents · blue: AlphaBot · purple: Beta<br>Candles: actual traded-price OHLC. Blue line: sampled YES bids. Green/red exit labels: realized gain/loss.</p><div id="record-chart">${chart(record,replay)}</div><div class="actions"><button id="replay-play">▶ Replay</button><button id="replay-latest">Latest saved</button></div><label>Replay position<input id="replay-range" type="range" min="0" max="${Math.max(0,frames.length-1)}" value="${replay??Math.max(0,frames.length-1)}"></label><p class="small">${esc(m.historyStatus||'Observed prices only')} · Last saved ${time(frames.at(-1)?.at)}${frames.length&&Date.now()-Date.parse(frames.at(-1).at)>120000?' · NOT LIVE / STALE':''}</p><details data-key="rules-${esc(m.ticker)}"><summary>Market identity, target & rules</summary><dl><div><dt>Official target</dt><dd>${m.floor_strike??'See rules'}</dd></div><div><dt>Trading close</dt><dd>${time(m.close_time)}</dd></div></dl><p>${esc(m.rules_primary||'Rules unavailable')}</p><p>${esc(m.rules_secondary||'')}</p><small>Contract cents and underlying reference prices are different. Coinbase spot is not the official settlement feed.</small></details><button id="record-export">Download this recording</button></section><section class="panel"><h2>Decisions & trade timeline</h2>${record.events.map(event).join('')||'<p>No decisions or trades recorded for this market.</p>'}</section>`;}
function recorded(){return selected?recordingDetail():recordingList();}
function settings(){const s=data.state;return `<section class="panel"><h2>Experiment</h2><p>${esc(s.mode.toUpperCase())} · Started ${time(s.startedAt)}</p><div class="actions"><button class="primary" data-control="start" ${s.mode==='running'?'disabled':''}>Resume paper test</button><button data-control="pause" ${s.mode!=='running'?'disabled':''}>Pause agents</button></div><p class="small">Paused means no new entries or AI decisions. Existing positions still receive exit attempts and official settlement updates.</p></section><section class="panel"><h2>Appearance & reading</h2><p>Black background · blue controls · green gains · red losses.</p><p>Details stay open until you close them. New data waits for you.</p></section><section class="panel"><h2>API budgets</h2><dl><div><dt>Research</dt><dd>$${s.budget.spent.toFixed(3)} / $${s.budget.cap}</dd></div><div><dt>Daily research cap</dt><dd>$${s.budget.dailyCap}</dd></div><div><dt>Image reservations / charges</dt><dd>$${((s.imageBudget?.spent||0)+(s.imageBudget?.reserved||0)).toFixed(2)} / $${s.imageBudget?.cap||1}</dd></div></dl><p class="small">Images use a conservative $0.10 reservation per attempt; actual provider billing may differ. Extra pictures require approval and $5 of earned fake profit.</p><p>Key safety stop: ${time(s.keyExpiresAt)}</p></section><section class="panel"><h2>Your records</h2><button id="export">Export account & event history</button><p><a href="practice.html">Open separate practice archive ↗</a></p><button id="logout">Sign out</button></section>`;}
const pages={home:['Your trading lab','Four simple places to follow the experiment.',home],recordings:['Recorded tickers','Actual recorded market data. Simulated trades.',recorded],trading:['Agent trading','What they chose, why, and what actually filled.',trading],profiles:['Agent profiles','Their identities, balances, results, and pictures.',profiles],loans:['Requests & approvals','You decide on loans and additional pictures.',loans],settings:['Settings','Experiment, budgets, and your records.',settings]};
function render(){if(!data)return;const open=new Set([...document.querySelectorAll('details[open][data-key]')].map(d=>d.dataset.key));$('#login').hidden=true;$('#dashboard').hidden=false;const [title,sub,fn]=pages[view];$('#title').textContent=title;$('#subtitle').textContent=sub;$('#run-status').textContent=`${data.state.mode.toUpperCase()} · Last market update ${time(data.state.lastTick)}${data.state.error?' · '+data.state.error:''}`;$('#content').innerHTML=fn();for(const d of document.querySelectorAll('details[data-key]'))if(open.has(d.dataset.key))d.open=true;for(const a of document.querySelectorAll('.bottom-nav a')){if(a.hash==='#'+view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}$('#nav-back').disabled=!navigation.canBack;void hydrateAvatars();}
async function hydrateAvatars(){await Promise.all([...document.querySelectorAll('[data-avatar]')].map(async el=>{const id=el.dataset.avatar;if(!id)return;try{if(!avatars.has(id))avatars.set(id,(async()=>{const r=await fetch('/api/lab/avatar?id='+encodeURIComponent(id),{headers:{Authorization:'Bearer '+await token()}});if(!r.ok)throw Error('Picture unavailable');const blob=await r.blob();return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});})());const src=await avatars.get(id);if(src&&el.isConnected)el.replaceChildren(Object.assign(document.createElement('img'),{src,alt:'Saved agent profile picture'}));}catch{avatars.delete(id);}}));}
async function supporting(){const list=await api('recordings');recordings=list.recordings;const events=[];let after=0;for(let page=0;page<1000;page++){const b=await api('history?after='+after);events.push(...b.events);if(b.events.length<500)break;after=b.events.at(-1).recordId;}history=events;}
async function refresh(force=false){if(!session||busy)return;busy=true;try{const next=await api('state');$('#connection-indicator').textContent='Connected';$('#message').textContent='';if(!data||force){data=next;pending=null;await supporting();$('#new-updates').hidden=true;render();}else if(next.revision!==data.revision){pending=next;$('#new-updates').hidden=false;}}catch(e){$('#message').textContent=e.message;$('#connection-indicator').textContent='Connection interrupted';if(!session){$('#login').hidden=false;$('#dashboard').hidden=true;}}finally{busy=false;}}
async function control(action,p={}){try{$('#message').textContent='Saving…';await api('control',{action,...p});await refresh(true);$('#message').textContent='Saved.';}catch(e){$('#message').textContent=e.message;}}
async function openRecord(t){selected=t;record=null;replay=null;clearInterval(playing);if(view!=='recordings')location.hash='recordings';render();try{record=await api('recording?ticker='+encodeURIComponent(t));if(!record.metadata)record.metadata={ticker:t,title:'Exact market: '+t,historyStatus:'No recording available for this older market yet.'};render();}catch(e){$('#message').textContent=e.message;}}
function download(value,name){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;if(!config){await initialize();if(!config)return;}try{const r=await fetch(config.url+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify({email:f.email.value,password:f.password.value})});if(!r.ok)throw Error('Sign-in failed. Check your DS HUB credentials.');session=await r.json();authSave();f.password.value='';await refresh(true);}catch(e){$('#login-error').textContent=e.message;}});
$('#nav-back').addEventListener('click',()=>{view=navigation.back();navigatingBack=true;location.hash=view;render();});
$('#new-updates').addEventListener('click',async()=>{await refresh(true);if(selected)await openRecord(selected);});
$('#content').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.record)return openRecord(b.dataset.record);if(b.hasAttribute('data-record-list')){selected='';record=null;clearInterval(playing);render();return;}if(b.dataset.control)return control(b.dataset.control);if(b.dataset.loan){const input=[...document.querySelectorAll('[data-amount]')].find(x=>x.dataset.amount===b.dataset.loan);return control('loan',{id:b.dataset.loan,amount:Math.round(Number(input.value)*100),approve:b.dataset.approve==='true'});}if(b.dataset.image)return control('image-review',{agent:b.dataset.agent,id:b.dataset.image,approve:b.dataset.approve==='true'});
 if(b.id==='logout'){session=null;authSave();location.reload();}if(b.id==='export'){await supporting();download({...data,events:history,kind:'market-lab-cloud-export',version:'0.5.0'},'DS-Market-Lab-0.5.0-session.json');}if(b.id==='record-export')download(record,'DS-Market-Lab-0.5.0-'+selected+'.json');if(b.id==='replay-latest'){clearInterval(playing);replay=null;$('#record-chart').innerHTML=chart(record);$('#replay-range').value=record.frames.length-1;}if(b.id==='replay-play'){clearInterval(playing);replay=0;playing=setInterval(()=>{if(view!=='recordings'||!record||replay>=record.frames.length-1){clearInterval(playing);return;}replay++;$('#record-chart').innerHTML=chart(record,replay);$('#replay-range').value=replay;},250);}});
$('#content').addEventListener('input',e=>{if(e.target.id==='replay-range'){clearInterval(playing);replay=Number(e.target.value);$('#record-chart').innerHTML=chart(record,replay);}});
window.addEventListener('hashchange',()=>{clearInterval(playing);view=navigatingBack?screen(location.hash.slice(1)):navigation.visit(location.hash.slice(1));navigatingBack=false;if(pending){data=pending;pending=null;$('#new-updates').hidden=true;void supporting().then(render);}render();window.scrollTo(0,0);});
setInterval(()=>{if(!document.hidden)void refresh();},15000);
async function initialize(){if(initializing)return initializing;initializing=(async()=>{const submit=$('#login-form button'),retry=$('#retry-connection');submit.disabled=true;retry.disabled=true;try{config=await loadConfig();submit.disabled=false;retry.hidden=true;$('#login-error').textContent='';$('#connection-status').textContent='Connected · Ready to sign in';if(session)await refresh(true);}catch(e){config=null;$('#connection-status').textContent='Connection interrupted';$('#login-error').textContent=e.message;retry.hidden=false;}finally{retry.disabled=false;initializing=null;}})();return initializing;}
$('#retry-connection').addEventListener('click',()=>initialize());window.addEventListener('online',()=>{if(!config)initialize();});window.addEventListener('pageshow',()=>{if(!config)initialize();});await initialize();
